#include "a_host_view.hpp"
#include "z3_a_guidance.h"
#include <nlohmann/json.hpp>
#include <iostream>
#include <set>
#include <stdexcept>
using J=nlohmann::json;
void check(bool v,char const* m){if(!v)throw std::runtime_error(m);}
std::shared_ptr<a2::Index> index_of(std::vector<std::pair<z3::expr,bool>> const& atoms){auto idx=std::make_shared<a2::Index>();unsigned id=0;for(auto const& kv:atoms){a2::Work w;w.deadline=a2::Clock::now()+std::chrono::seconds(1);auto n=a2::canonical(a2::HostView{},kv.first,w);check(n.complete,"test atom normalization failed");auto& en=idx->entries[n.key];en.original_exact=n.exact;bool desired=kv.second;en.rules.push_back({id++,desired!=n.negated,desired?1ull:0ull,desired?0ull:1ull,desired?1ull:0ull,desired?0ull:1ull});}idx->version=1;return idx;}
void install(z3::solver& s,std::shared_ptr<a2::Index> const& idx,unsigned mode=2,double exposure=45,unsigned q=1){Z3_solver_set_A_guidance(s.ctx(),s,&idx,q,1,mode,exposure,45,1);s.ctx().check_error();}
J stats(z3::solver& s){return J::parse(Z3_solver_get_A_guidance_stats(s.ctx(),s));}
void clear(z3::solver& s){Z3_solver_clear_A_guidance(s.ctx(),s);s.ctx().check_error();}
J choice(unsigned mode,std::string path){z3::context c;auto x=c.int_const("x");auto atom0=c.bool_const("p"),atom10=c.bool_const("q");auto f=(atom0||atom10)&&(x>=0)&&(x<=10);z3::solver s=path=="temporary"?z3::tactic(c,"smt").mk_solver():z3::solver(c);s.add(f);z3::expr_vector asms(c);if(path=="persistent")asms.push_back(x>=0);auto idx=index_of({{atom0,true},{atom10,true}});auto count=s.assertions().size();if(mode)install(s,idx,mode);auto result=s.check(asms);check(result==z3::sat,"choice SAT");auto m=s.get_model();check(m.eval(f,true).is_true(),"choice illegal model");auto st=mode?stats(s):J::object();check(count==s.assertions().size(),"metadata changed assertions");if(mode){check(st["b_encoded"]==0&&st["b_internalized"]==0,"B isolation");for(auto const& a:st["actions"])check(a["native_var"]==a["actual_var"],"A changed variable");clear(s);check(idx->active==0,"request not released");}return {{"model",m.to_string()},{"stats",st}};}
int main(){try{J evidence=J::array();
 for(auto path:{"persistent","temporary","default"}){auto off=choice(0,path),observe=choice(1,path),apply=choice(2,path);check(off["model"]==observe["model"],"silent observe changed model");check(observe["stats"]["phase_overrides"]==0,"observe changed phase");std::cerr<<"choice "<<path<<" "<<apply.dump()<<"\n";if(std::string(path)!="default")check(apply["stats"]["phase_overrides"].get<unsigned>()>0,"no actual override witness");evidence.push_back({{"test",std::string("choice_")+path},{"off",off},{"observe",observe},{"apply",apply}});}
 {z3::context c;auto p=c.bool_const("p"),q=c.bool_const("q");auto s=z3::tactic(c,"sat").mk_solver();s.add(p||q);auto idx=index_of({{p,true}});install(s,idx);check(s.check()==z3::sat,"SAT leaf");auto st=stats(s);check(st["actions"].empty(),"guided SAT leaf");bool seen=false;for(auto const& t:st["stages"])seen|=t["tactic_name"]=="sat.non_smt_leaf";check(seen,"SAT leaf missing");evidence.push_back({{"test","non_smt_leaf"},{"stats",st}});clear(s);}
 {z3::context c;z3::solver s(c);auto x=c.int_const("x");s.add(x>=0&&x<=3);auto idx=index_of({{x==0,false},{x==3,true}});for(int value=0;value<4;++value){z3::expr_vector asms(c);asms.push_back(x==value);install(s,idx,2,45,value+1);check(s.check(asms)==z3::sat,"projected solution lost");check(s.get_model().eval(x).get_numeral_int()==value,"wrong projection");clear(s);}evidence.push_back({{"test","all_projected_solutions"},{"count",4}});}
 {z3::context c;z3::solver s(c);auto x=c.int_const("x");s.add(x>=0);std::vector<std::pair<z3::expr,bool>> atoms;for(unsigned i=0;i<90;++i){auto a=c.bool_const(("a"+std::to_string(i)).c_str()),b=c.bool_const(("b"+std::to_string(i)).c_str());s.add(a||b);atoms.emplace_back(a,true);atoms.emplace_back(b,true);}auto idx=index_of(atoms);z3::expr_vector asms(c);asms.push_back(x>=0);install(s,idx);check(s.check(asms)==z3::sat,"quota SAT");auto st=stats(s);check(st["ordinary"].get<unsigned>()>64,"window not exhausted");check(st["suggestions"].get<unsigned>()<=4,"quota violated");std::set<unsigned> targets;for(auto const& a:st["actions"]){check(a["decision_id"].get<unsigned>()<=64,"late advice");for(auto const& t:a["support"])check(targets.insert(t["node"].get<unsigned>()).second,"repeated target");}evidence.push_back({{"test","window_quota"},{"stats",st}});clear(s);}
 {z3::context c;auto x=c.int_const("x");z3::solver one(c),two(c);one.add(x==0||x==10);two.add(x==3);auto idx=index_of({{x==10,true}});install(one,idx);check(two.check()==z3::sat&&stats(two).empty(),"solver ownership leaked");check(one.check()==z3::sat,"ownership main");clear(one);one.push();one.add(x==0);install(one,idx);check(one.check()==z3::sat,"push");clear(one);one.pop();install(one,idx);check(one.check()==z3::sat,"pop");clear(one);one.reset();one.add(x==2);install(one,idx);check(one.check()==z3::sat,"reset");clear(one);one.set("rlimit",1u);install(one,idx);check(one.check()==z3::unknown,"expected native cancellation");clear(one);one.set("rlimit",0u);check(one.check()==z3::sat,"cancel cleanup poisoned reuse");evidence.push_back({{"test","ownership_pop_reset_native_cancel"},{"passed",true}});}
 std::cout<<J({{"passed",true},{"tests",evidence}}).dump(2)<<'\n';
 }catch(std::exception const& e){std::cerr<<e.what()<<'\n';return 1;}}
